USE [olist_dwh];
GO

--=========================================================================
-- create the product dimension table
-- i am creating the product dimension in the gold schema.
-- product_key will be the surrogate key generated by sql server.
-- product_id will identify each product from the silver layer.
-- the remaining columns will provide descriptive product information.
--=========================================================================

IF OBJECT_ID('[gold].[dim_product]', 'U') IS NULL
BEGIN
    CREATE TABLE [gold].[dim_product]
    (
        product_key INT IDENTITY(1,1) NOT NULL,
        product_id VARCHAR(50) NOT NULL,
        product_category_name NVARCHAR(255) NOT NULL,
        product_name_length INT NULL,
        product_description_length INT NULL,
        product_photos_qty INT NULL,
        product_weight_g INT NULL,
        product_length_cm DECIMAL(10,2) NULL,
        product_height_cm DECIMAL(10,2) NULL,
        product_width_cm DECIMAL(10,2) NULL,

        CONSTRAINT PK_dim_product
            PRIMARY KEY (product_key)
    );
END;
GO

--=========================================================================
-- create a unique index for the product business key
-- i am ensuring that each product_id can only appear once
-- in the dimension.
-- this prevents duplicate products from being inserted.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM sys.indexes
    WHERE name = 'UX_dim_product'
      AND object_id = OBJECT_ID('[gold].[dim_product]')
)
BEGIN
    CREATE UNIQUE NONCLUSTERED INDEX UX_dim_product
    ON [gold].[dim_product] (product_id);
END;
GO

--=========================================================================
-- insert the unknown product record
-- i am inserting an unknown product with product_key = -1.
-- this record will be used when a product cannot be matched
-- during the fact table loading process.
-- identity_insert allows me to insert -1 manually.
-- the if not exists check prevents duplicate unknown records.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM [gold].[dim_product]
    WHERE product_key = -1
)
BEGIN
    SET IDENTITY_INSERT [gold].[dim_product] ON;

    INSERT INTO [gold].[dim_product]
    (
        product_key,
        product_id,
        product_category_name,
        product_name_length,
        product_description_length,
        product_photos_qty,
        product_weight_g,
        product_length_cm,
        product_height_cm,
        product_width_cm
    )
    VALUES
    (
        -1,
        'Unknown',
        'Unknown',
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL
    );

    SET IDENTITY_INSERT [gold].[dim_product] OFF;
END;
GO